pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let mut score = cpu_norm * cpu_norm + ram_norm * ram_norm;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, _node_capacity_cpu: u32, _node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / _node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / _node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let lookahead_factor = if next_job_cpu == 0 && next_job_ram == 0 { 0.5 } else { 1.0 };
    let dynamic_factor = ((step_index as f64) * total_jobs as f64).sin() / 2.0 + 0.5;

    let lookahead_score = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        -10.0
    } else {
        lookahead_factor * (next_job_cpu as f64 / mean_cpu_residual) + lookahead_factor * (next_job_ram as f64 / mean_ram_residual)
    };

    let packing_bonus = if node_residual_cpu > next_job_cpu && node_residual_ram > next_job_ram {
        -5.0
    } else {
        0.0
    };

    let score = cpu_norm + ram_norm - imbalance_penalty * dynamic_factor + lookahead_score + packing_bonus;

    // Introduce horizon-aware placement logic
    let horizon_factor = (step_index as f64 / total_jobs as f64).powi(2);

    // Balance CPU and RAM usage with non-linear conditionals
    let cpu_balance = if cpu_norm > ram_norm { 1.0 } else { -1.0 };
    let ram_balance = if ram_norm > cpu_norm { 1.0 } else { -1.0 };

    // Introduce imbalance penalties
    let imbalance_penalty = (cpu_norm - ram_norm).abs() * horizon_factor;

    score = score * 0.95 + imbalance_penalty;
    score = score * 0.95 + (node_residual_ram as f64 / _node_capacity_ram as f64) * 0.1;
    score = score * 0.95 + (cpu_balance + ram_balance).abs() * 0.05;

    score
}
